mapper.sql:
select av.achievement_id as "sourceAchievementId", av.evaluation_year as "evaluationYear", dcc.area_code as "areaCode", dcc.department_organization_code as "organizationCode", av.processed_by as "targetUserId", case when av.next_status in ('CERTIFIED', '인증') then '인증' else av.next_status end as "sourceStatus", 'FACULTY_ACHIEVEMENT' as "achievementType", concat('업적 ', av.achievement_id) as "achievementTitle", case when exists ( select 1 from evaluation_materials em where em.source_achievement_id = av.achievement_id and em.evaluation_year = av.evaluation_year and em.area_code = dcc.area_code and em.target_user_id = av.processed_by and em.deleted_yn = 'N' ) then '생성완료' else '미생성' end as "generationStatus" from achievement_verifications av join department_chair_confirmations dcc on dcc.achievement_id = av.achievement_id where av.next_status in ('CERTIFIED', '인증') and not exists ( select 1 from achievement_verifications newer where newer.achievement_id = av.achievement_id and (newer.processed_at, newer.verification_id) > (av.processed_at, av.verification_id) ) and not exists ( select 1 from evaluation_materials em where em.source_achievement_id = av.achievement_id and em.evaluation_year = av.evaluation_year and em.area_code = dcc.area_code and em.target_user_id = av.processed_by and em.deleted_yn = 'N' )
and av.evaluation_year = #{criteria.normalizedEvaluationYear}
and dcc.area_code = #{criteria.normalizedAreaCode}
and dcc.department_organization_code = #{criteria.normalizedOrganizationCode}
and av.processed_by = #{criteria.normalizedTargetUserId}

mapper.insert:
insert into evaluation_materials (evaluation_year, area_code, target_user_id, source_achievement_id, generation_batch_id,
    material_status, material_origin, material_snapshot_json, calculated_score, request_id, created_by, updated_by)
select #{target.evaluationYear}, #{target.areaCode}, #{target.targetUserId}, #{target.sourceAchievementId}, #{batchId},
       '인증', 'BATCH_GENERATED',
       jsonb_build_object(
           'sourceAchievementId', #{target.sourceAchievementId},
           'sourceStatus', #{target.sourceStatus},
           'achievementType', #{target.achievementType},
           'achievementTitle', #{target.achievementTitle}
       ),
       0, #{requestId}, #{requestUserId}, #{requestUserId}
where not exists (
    select 1 from evaluation_materials em
    where em.source_achievement_id = #{target.sourceAchievementId}
      and em.evaluation_year = #{target.evaluationYear}
      and em.area_code = #{target.areaCode}
      and em.target_user_id = #{target.targetUserId}
      and em.deleted_yn = 'N'
)
